function parseBracket(text, start) {
  let index = start
  let negated = false

  // Check for negation (leading ! or ^)
  if (index < text.length && (text[index] === '!' || text[index] === '^')) {
    negated = true
    index += 1
  }

  const items = []

  // Special case: ] at the start (after potential negation) is literal
  if (index < text.length && text[index] === ']') {
    items.push({ from: ']', to: ']' })
    index += 1
  }

  // Parse the body
  while (index < text.length) {
    // Check for closing ]
    if (text[index] === ']') {
      return { node: { type: 'class', negated, items }, index: index + 1 }
    }

    // Get the first character (handling escapes)
    let firstChar
    if (text[index] === '\\') {
      if (index + 1 >= text.length) throw new GlobError('trailing backslash in pattern')
      firstChar = text[index + 1]
      index += 2
    } else {
      firstChar = text[index]
      index += 1
    }

    // Check if this is the start of a range
    // A range is: char-char, where - is not escaped and not followed by ] (or end)
    if (index < text.length && text[index] === '-' &&
        index + 1 < text.length && text[index + 1] !== ']') {
      // This is a range
      index += 1 // skip the '-'
      let secondChar
      if (text[index] === '\\') {
        if (index + 1 >= text.length) throw new GlobError('trailing backslash in pattern')
        secondChar = text[index + 1]
        index += 2
      } else {
        secondChar = text[index]
        index += 1
      }
      items.push({ from: firstChar, to: secondChar })
    } else {
      // Not a range, just a literal character
      items.push({ from: firstChar, to: firstChar })
      // If there's a - right after that can't be part of a range, add it as literal
      if (index < text.length && text[index] === '-' &&
          (index + 1 >= text.length || text[index + 1] === ']')) {
        items.push({ from: '-', to: '-' })
        index += 1
      }
    }
  }

  // If we reach here without finding a closing ], it's unterminated
  throw new GlobError('unterminated bracket in pattern')
}"}

